import{_ as t,o,c as i,a5 as a}from"./chunks/framework.BfQ7H7Qx.js";const m=JSON.parse('{"title":"FR 3.9.3 — View Invoice History","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/08-subscription-billing/3-9-3-view-invoice-history/spec.md","filePath":"feature/srs/08-subscription-billing/3-9-3-view-invoice-history/spec.md"}'),n={name:"feature/srs/08-subscription-billing/3-9-3-view-invoice-history/spec.md"};function r(d,e,c,s,l,g){return o(),i("div",null,[...e[0]||(e[0]=[a('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-9-3-—-view-invoice-history" tabindex="-1">FR 3.9.3 — View Invoice History <a class="header-anchor" href="#fr-3-9-3-—-view-invoice-history" aria-label="Permalink to &quot;FR 3.9.3 — View Invoice History&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.9.3</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-124</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">View Invoice History</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">Subscription &amp; Billing (<code>3.9</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Admin</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-20, BR-64</code></td></tr><tr><td style="text-align:left;"><strong>Message Codes</strong></td><td style="text-align:left;"><code>MSG01, MSG02, MSG03, MSG07</code></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified (Consolidates <code>subscription-invoice-history</code> &amp; <code>admin-invoice-history</code>)</td></tr></tbody></table><h2 id="_1-objective-business-value" tabindex="-1">1. Objective &amp; Business Value <a class="header-anchor" href="#_1-objective-business-value" aria-label="Permalink to &quot;1. Objective &amp; Business Value&quot;">​</a></h2><p>Provide cursor-paginated, read-only Invoice &amp; Payment History, right-side sliding Order Detail Drawer (<code>1/3</code> viewport at <code>&gt;= 1024px</code>), verified PDF receipt download (<code>FULFILLED</code> + <code>VERIFIED</code> payment only, explicitly marked non-VAT receipt), and on-demand SePay API v2 transaction verification for both Agency <code>Owner</code> (<code>/agency/:agencyId/invoices</code>) and platform <code>Admin</code> (<code>/admin?view=revenue</code> / <code>AdminInvoicesPanel</code>).</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an authorized <code>Owner, Admin</code>, I want to execute <strong>View Invoice History</strong> with strong ACID financial/administrative guarantees, deterministic concurrency protection, and complete audit logging so that BrandHub&#39;s operations strictly satisfy <code>BR-20, BR-64</code> without manual database intervention.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Canonical Role &amp; Tenant Security:</strong> Server-side authorization enforces <code>Owner, Admin</code> on every request (<code>Admin</code> verified against live DB <code>user_system_roles</code>; <code>Owner</code>/<code>Manager</code>/<code>Creator</code> verified against live <code>agencies</code> / <code>workspace_members</code>). Unauthorized callers receive <code>403 FORBIDDEN</code> (<code>MSG07</code>) or scoped <code>404 NOT_FOUND</code> on IDOR probes.</li><li><strong>Core Domain &amp; Financial Invariants:</strong></li></ol><ul><li><strong>1. Strict Tenant &amp; IDOR Protection:</strong> <code>InvoiceHistoryService</code> verifies current <code>Owner</code> of <code>agencyId</code> on every request; former owners, non-owners, or cross-agency <code>orderId</code> probes receive <code>404/403</code> without leaking order metadata. <code>Admin</code> endpoints require fresh DB <code>ADMIN</code> verification.</li><li><strong>2. Verified Receipt Gate:</strong> Receipt download (<code>brandhub-receipt-{orderId}.pdf</code>) is generated <strong>only</strong> when the order is <code>FULFILLED</code> with a <code>VERIFIED</code> payment matching the order amount, clearly stating it is a payment confirmation receipt rather than a statutory tax/VAT invoice.</li><li><strong>3. Safe On-Demand SePay API v2 Lookup:</strong> Executed strictly outside PostgreSQL transactions via <code>SePayTransactionClient</code> (<code>transaction_content = provider_order_code</code>), verifying incoming direction, merchant account match, and post-order timestamp, returning minimal sanitized metadata (never exposing merchant bank balance or third-party PII) and never mutating order state on <code>GET</code>.</li></ul><ol start="3"><li><strong>Auditability &amp; Idempotency:</strong> Every mutation records correlation <code>requestId</code> and structured audit evidence (<code>audit_logs</code> / <code>billing_audit_events</code> / <code>admin_account_operations</code>), and supports safe retry without duplicate financial side effects.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> All headings, table columns, status pills, dialogs, validation hints, and error banners use key-parallel translations (<code>subscription.invoices.*</code>, <code>subscription.invoiceDrawer.*</code>, <code>admin.invoices.*</code> in <code>src/i18n/locales/{vi,en}/subscription.json</code> &amp; <code>admin.json</code>) on <code>brandhub-web</code> and <code>tr()</code> on <code>brandhub-mobile-app</code> — zero hardcoded Vietnamese or English text in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All components (<code>pages/agency</code> Payment History + <code>InvoiceDetailDrawer</code> (<code>w-full lg:w-1/3</code> right-side sheet), <code>pages/admin/components/AdminInvoicesPanel.tsx</code>, <code>pages/admin/InvoicesPage.tsx</code> on Web and <code>src/screens/billing/InvoiceHistoryScreen.tsx</code>, <code>InvoiceDetailScreen.tsx</code>, <code>src/screens/admin/AdminInvoicesScreen.tsx</code> on Mobile) use semantic CSS variables / Tailwind <code>dark:</code> variants and <code>useAppPreferences().palette</code> tokens with WCAG AA contrast across Light and Dark modes.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>pages/agency</code> Payment History + <code>InvoiceDetailDrawer</code> (<code>w-full lg:w-1/3</code> right-side sheet), <code>pages/admin/components/AdminInvoicesPanel.tsx</code>, <code>pages/admin/InvoicesPage.tsx</code></li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/billing/InvoiceHistoryScreen.tsx</code>, <code>InvoiceDetailScreen.tsx</code>, <code>src/screens/admin/AdminInvoicesScreen.tsx</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / Busy:</strong> Skeleton placeholders on initial query; disabled submit button + spinner during in-flight mutation to prevent double-submit races.</li><li><strong>Empty:</strong> Contextual localized empty state (e.g. zero invoices/moderation items/users matching filter) with zero fabricated mock data.</li><li><strong>Success:</strong> Scoped <code>TanStack Query</code> cache invalidation, updated KPI/row state, and localized confirmation toast.</li><li><strong>Conflict / Error:</strong> Explicit <code>409</code> stale-revision reload prompt or localized validation banner preserving user draft inputs.</li></ul></li></ul><h2 id="_5-api-contract" tabindex="-1">5. API Contract <a class="header-anchor" href="#_5-api-contract" aria-label="Permalink to &quot;5. API Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method &amp; Endpoint</th><th style="text-align:left;">Auth / Guard</th><th style="text-align:left;">Controller &amp; Service Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET /api/v1/billing/agencies/{agencyId}/invoices?cursor={c}&amp;limit={20}&amp;status={s}&amp;kind={k}&amp;from={iso}&amp;to={iso}</code></td><td style="text-align:left;">Bearer (<code>Owner</code>)</td><td style="text-align:left;"><code>InvoiceHistoryController.list()</code> -&gt; cursor-paginated <code>(created_at, id) DESC</code> projection from <code>billing_orders</code></td></tr><tr><td style="text-align:left;"><code>GET /api/v1/billing/agencies/{agencyId}/invoices/{orderId}</code></td><td style="text-align:left;">Bearer (<code>Owner</code>)</td><td style="text-align:left;"><code>InvoiceHistoryController.detail()</code> -&gt; payer UUID, plan snapshot, exact string amount, attempts, fulfillment &amp; review reason</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/billing/agencies/{agencyId}/invoices/{orderId}/receipt</code></td><td style="text-align:left;">Bearer (<code>Owner</code>)</td><td style="text-align:left;"><code>InvoiceHistoryController.receipt()</code> -&gt; <code>application/pdf</code> (<code>Cache-Control: no-store</code>) only when <code>FULFILLED</code> + <code>VERIFIED</code> payment</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/billing/agencies/{agencyId}/invoices/{orderId}/sepay-transactions?page={1}</code></td><td style="text-align:left;">Bearer (<code>Owner</code>)</td><td style="text-align:left;"><code>InvoiceHistoryController.lookup()</code> -&gt; <code>InvoiceProviderService</code> read-only SePay API v2 lookup outside DB transaction (<code>&lt;= 1 call / 400ms</code> rate gate)</td></tr><tr><td style="text-align:left;">`GET /api/v1/admin/billing/invoices &amp; /agencies/{agencyId}/invoices/{orderId}[/receipt</td><td style="text-align:left;">/sepay-transactions]`</td><td style="text-align:left;">Bearer (<code>Admin</code>)</td></tr></tbody></table><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><code>FORBIDDEN</code> (<code>403</code>, <code>MSG07</code>): Caller lacks <code>Owner, Admin</code> permission or attempts cross-Agency/cross-Workspace access.</li><li><code>CONFLICT</code> (<code>409</code>, <code>MSG03</code>): Stale <code>expectedRevision</code> / <code>rowVersion</code>, duplicate idempotency key with mutated payload, or prohibited self-sanction/last-Admin demotion.</li><li><code>BAD_REQUEST</code> / <code>PAYLOAD_TOO_LARGE</code> (<code>400</code> / <code>413</code>, <code>MSG02</code> / <code>MSG14</code>): Invalid date range, negative/unsafe integer amount, malformed CSV, or de-scoped operation (e.g., plan downgrade or non-SePay provider).</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Related SRS FRs &amp; Modules:</strong> <a href="./../3-9-2-make-payment-sepay/spec.html">FR 3.9.2 — Make Payment (SePay)</a> · <a href="./../../09-admin-functions/3-10-13-view-revenue-dashboard/spec.html">FR 3.10.13 — View Revenue Dashboard</a></li><li><strong>BA Domain Baseline:</strong> <a href="./../../../../ba/08-subscription-billing.html">BA Specification</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Verified via JUnit 5 + isolated PostgreSQL/MongoDB integration tests, TypeScript/Playwright Web checks, Jest Mobile tests, <code>vi.json</code>/<code>en.json</code> key parity, and Light/Dark theme audit (<a href="./test.html">test.md</a>).</li><li><strong>Out of Scope:</strong> De-scoped capabilities (subscription plan downgrade, PayOS/VNPay/Stripe gateways, or copyright/plagiarism moderation).</li></ul>',21)])])}const u=t(n,[["render",r]]);export{m as __pageData,u as default};
